import{_ as a,a as t,c as n,ac as r}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 7 Are you a teacher?","description":"学习 a/an 与职业名词，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 7 Are you a teacher?","description":"学习 a/an 与职业名词，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 a/an 与职业名词，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 6 What make is it?","link":"/life/english/new-concept/book-1/unit-01/lesson-006"},"next":{"text":"第一册：英语初阶 · Lesson 8 What's your job?","link":"/life/english/new-concept/book-1/unit-01/lesson-008"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 6 What make is it?","link":"/life/english/new-concept/book-1/unit-01/lesson-006"},"next":{"text":"第一册：英语初阶 · Lesson 8 What's your job?","link":"/life/english/new-concept/book-1/unit-01/lesson-008"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-01/lesson-007.md","filePath":"life/english/new-concept/book-1/unit-01/lesson-007.md"}`),i={name:"life/english/new-concept/book-1/unit-01/lesson-007.md"};function o(s,e,l,h,c,d){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="第一册-英语初阶-·-lesson-7-are-you-a-teacher" tabindex="-1">第一册：英语初阶 · Lesson 7 Are you a teacher? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-7-are-you-a-teacher" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 7 Are you a teacher?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-01/overview">单元 1</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-008">配套课 Lesson 8</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>询问职业并给出完整身份信息 本课要掌握a/an 与职业名词，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>teacher</td><td>/ˈtiːtʃə/</td><td>n.</td><td>教师</td><td>a teacher</td></tr><tr><td>engineer</td><td>/ˌendʒɪˈnɪə/</td><td>n.</td><td>工程师</td><td>an engineer</td></tr><tr><td>nurse</td><td>/nɜːs/</td><td>n.</td><td>护士</td><td>a nurse</td></tr><tr><td>job</td><td>/dʒɒb/</td><td>n.</td><td>工作；职业</td><td>a new job</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>an engineer — 元音音素前用 an</li><li>be a nurse — 说明职业</li></ul><h2 id="语法讲解-a-an-与职业名词" tabindex="-1">语法讲解：a/an 与职业名词 <a class="header-anchor" href="#语法讲解-a-an-与职业名词" aria-label="Permalink to &quot;语法讲解：a/an 与职业名词&quot;">​</a></h2><p>单数可数职业名词作表语时一般加 a 或 an。选择取决于紧接着的读音，不是字母名称；engineer 前用 an，teacher 前用 a。What is your job? 询问职业，回答可用 I am a/an ...。be 必须与主语一致：I am、you are、he/she is；不能用职业名词直接作谓语。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>My sister is an engineer.</p></blockquote><p>我姐姐是一名工程师。</p><p>My sister 为第三人称单数主语，后接 is；engineer 的首音是元音音素，因此用 an，而非 a。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>复数职业前不加 a/an；teachers 与 are 配合，不能写 a teachers。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“My sister is an engineer.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>My sister is an engineer. Are your parents teachers?</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“询问职业并给出完整身份信息”写两至三句，再读给同伴听。至少使用一次a/an 与职业名词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>My sister 为第三人称单数主语，后接 is；engineer 的首音是元音音素，因此用 an，而非 a。 Your parents 是复数主语，问句将 are 提前；teachers 为复数职业，不加 a/an。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填冠词：My sister is ___ engineer.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> an</p><p><strong>解析：</strong> 按本课规则判断：单数可数职业名词作表语时一般加 a 或 an。选择取决于紧接着的读音，不是字母名称；engineer 前用 an，teacher 前用 a。What is your job? 询问职业，回答可用 I am a/an ...。be 必须与主语一致：I am、you are、he/she is；不能用职业名词直接作谓语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“我姐姐是一名工程师。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> My sister is an engineer.</p><p><strong>解析：</strong> My sister 为第三人称单数主语，后接 is；engineer 的首音是元音音素，因此用 an，而非 a。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：Are your parents teachers?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 你的父母是教师吗？</p><p><strong>解析：</strong> Your parents 是复数主语，问句将 are 提前；teachers 为复数职业，不加 a/an。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：a/an 与职业名词。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-006">上一课</a> · <a href="/life/english/new-concept/book-1/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-008">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",o]]);export{p as __pageData,b as default};
